# Generated by build.py from recipe.yml for recipe s3-resume-a-ranged-download. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'dl', 'store/media' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'get-range.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Usage: sh get-range.sh URL FIRST LAST FILE [curl options...]`n# Fetches bytes FIRST to LAST of an object into FILE. When a try ends short, the next one asks`n# only for the bytes after those FILE holds; at most 5 tries. Prints each try's Range, status,`n# bytes received and curl's exit code, then the bytes fetched in all. An error status (4xx, 5xx)`n# is not a lost connection: the script stops there, exit 1.`nurl=`$1 first=`$2 last=`$3 file=`$4`nshift 4`n: > `"`$file`"`ntries=0 fetched=0`nwhile :; do`n  have=`$(wc -c < `"`$file`" | tr -d ' ')`n  from=`$((first + have))`n  if [ `"`$from`" -gt `"`$last`" ]; then break; fi`n  if [ `"`$tries`" -ge 5 ]; then echo `"gave up after `$tries tries`" >&2; exit 1; fi`n  tries=`$((tries + 1))`n  got=`$(curl -s -f `"`$@`" -r `"`$from-`$last`" -o `"`$file.try`" -w `"%{http_code} %{size_download}`" `"`$url`")`n  code=`$?`n  echo `"bytes=`$from-`$last: `$got, exit `$code`"`n  case `"`$got`" in 4*|5*) exit 1 ;; esac`n  fetched=`$((fetched + `${got#* }))`n  if [ -f `"`$file.try`" ]; then cat `"`$file.try`" >> `"`$file`"; rm -f `"`$file.try`"; fi`ndone`necho `"fetched `$fetched bytes for a range of `$((last - first + 1))`"`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1,DNS:*.s3.us-east-1.amazonaws.com"'
cmd /c 'openssl rand -out store/media/big.bin 4000000'
$server0 = Start-Process surl -ArgumentList '--directory', 'store', '--cert', 'server.pem', '--key', 'server.key', '--user', 'AKIAIOSFODNN7EXAMPLE:s3cret', '--fault', '"drop;after-bytes=1500000;close=graceful"', 's3://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh get-range.sh https://media.s3.us-east-1.amazonaws.com/big.bin 0 1999999 dl/part0 --max-time 30 --cacert server.pem --connect-to ::127.0.0.1:8080 --aws-sigv4 aws:amz:us-east-1:s3 -u AKIAIOSFODNN7EXAMPLE:s3cret } finally { Stop-Process $server0 }
